void SortedIntSet::insert(int value) {
assert(size() < MAX_SIZE);
if (!contains(value)) {
int index = num_elements;
while (index > 0 && elements[index - 1] > value) {
elements[index] = elements[index - 1];
--index;
}
elements[index] = value;
++num_elements;
}
}
Similarly, to remove an item, we must shift the remaining elements leftward in order to maintain our representation
invariants.
