void SortedIntSet::remove(int value) {
int index = indexOf(value);
if (index != -1) {
for (; index < num_elements - 1; ++index) {
elements[index] = elements[index + 1];
}
--num_elements;
}
}
The advantage of sorting is that we don’t have to look through all the elements to determine the location of a value.
Instead, we can use binary search, which eliminates half the search space in each step:
• Compare the value we are looking for to the middle element among the remaining items.
• If the value is equal to the middle element, we have found its index.
• If the value is less than the middle element, we know it must be to the left, if it is in the set. Thus, we need only
repeat the search on the items in the first half.
• If the value is greater than the middle element, we know it must be to the right, if it is in the set. Thus, we need
only repeat the search on the items in the second half.
• If we have run out of elements to search, the value is not in the set.
The following implements this algorithm:
int SortedIntSet::indexOf(int value) const {
int start = 0;
int end = num_elements;
while (start < end) {
int middle = start / 2 + end / 2;
if (value == elements[middle]) {
return middle;
} else if (value < elements[middle]) {
end = middle;
} else {
start = middle + 1;
}
}
return -1;
}
Since half the search space is eliminated in each step, this algorithm takes time that is logarithmic in the size of the set.
We denote this as O(log 𝑛), where 𝑛is the number of elements in the set.
For a set of size 𝑛, the following compares the worst-case runtime of each operation on unsorted and sorted sets:
